import{_ as t}from"./chunks/merge.ZJ0pW7Ba.js";import{_ as o,o as a,c as r,a4 as s}from"./chunks/framework.bruR1JhL.js";const n="/tilepress/screenshots/organize.webp",f=JSON.parse('{"title":"Combine, split & pages","description":"Merge PDFs, split them, reorder, rotate and crop pages, and add page numbers.","frontmatter":{"title":"Combine, split & pages","description":"Merge PDFs, split them, reorder, rotate and crop pages, and add page numbers."},"headers":[],"relativePath":"docs/pdf-pages.md","filePath":"docs/pdf-pages.md","lastUpdated":1795509372000}'),i={name:"docs/pdf-pages.md"};function d(l,e,g,h,p,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="combine-split-pages" tabindex="-1">Combine, split &amp; pages <a class="header-anchor" href="#combine-split-pages" aria-label="Permalink to &quot;Combine, split &amp; pages&quot;">​</a></h1><p>These tools change which pages a PDF has, their order and their shape: merge several files, split one apart, reorder and rotate pages, crop margins and stamp page numbers. In the app this category is the <strong>Pages</strong> tab under <strong>Documents</strong>.</p><p>Merge PDF keeps its own list of files. The other five tools work on one open PDF, and they share it: open a file in Split PDF, switch to Rotate PDF, and the same file is already there. To open a PDF, drag it from the Explorer onto the tool, click <strong>Open PDF…</strong>, or click <strong>Use</strong> followed by the name of the PDF selected in the Explorer. You can also right-click a PDF in the Explorer and choose <strong>Open in PDF tools</strong>, which opens it in the page tool you used last (or in Organize PDF if that was Merge PDF). See <a href="/tilepress/docs/interface">The Tilepress window</a> for the Explorer and the other general controls.</p><p>Every tool saves a <strong>new</strong> file and leaves the original alone. When it&#39;s done, a <strong>Saved</strong> card lists the result with <strong>Open</strong> and <strong>Show in folder</strong> buttons. When the result is a single PDF, <strong>Keep editing this file</strong> opens it straight away for the next step. Each run is also listed in the <a href="/tilepress/docs/history">History</a>.</p><details class="details custom-block"><summary>How to type page ranges</summary><p>Several tools take a list of pages. They all read it the same way:</p><ul><li>Single pages and ranges, separated by commas or semicolons: <code>1-3, 5, 8-10</code>.</li><li>Open-ended ranges: <code>8-</code> means page 8 to the end, <code>-4</code> means pages 1 to 4.</li><li>The words <code>all</code>, <code>odd</code> and <code>even</code>.</li></ul><p>A range that goes past the last page, or runs backwards (<code>5-2</code>), is reported as an error and nothing is saved.</p></details><h2 id="merge-pdf" tabindex="-1">Merge PDF <a class="header-anchor" href="#merge-pdf" aria-label="Permalink to &quot;Merge PDF&quot;">​</a></h2><p>Merge PDF combines several PDFs into one document, in the order of the list. You can take only some pages from each file.</p><p><img src="'+t+'" alt="Merge PDF with three PDFs in the list"></p><h3 id="how-to-use-it" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Merge PDF</strong>.</li><li>Click <strong>Add PDFs…</strong> and choose one or more files. You can also drag PDFs from the Explorer into the list, or click <strong>Add</strong> followed by the name of the PDF selected in the Explorer.</li><li>Put the files in order. Drag a row up or down, or use its <strong>Move up</strong> and <strong>Move down</strong> buttons. <strong>Sort A–Z</strong> sorts the list by file name.</li><li>To take only some pages from a file, type them in that file&#39;s page box (it shows &quot;All <em>N</em> pages&quot; while empty). The number of pages it selects appears underneath.</li><li>Click <strong>Merge and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><h3 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td>Page box (per file)</td><td>The pages to take from that file, for example <code>2-5, 9</code>. Empty takes every page.</td><td>Empty (all pages)</td></tr><tr><td><strong>Add a bookmark for each file</strong></td><td>Adds a bookmark named after each file (without <code>.pdf</code>) that jumps to its first page in the merged document.</td><td>On</td></tr></tbody></table><p>The bar at the bottom shows how many files and pages the result will have. <strong>Remove</strong> (the × on a row) takes a file off the list, and <strong>Clear list</strong> empties it.</p><h3 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>Only PDF files can be added. You can add the same file more than once, for example with different page ranges.</li><li>Pages are taken in the order you type them, so <code>5, 1-4</code> puts page 5 first. A page listed twice appears twice.</li><li>The Save dialog suggests the first file&#39;s name with <code>_merged</code> added, for example <code>report_merged.pdf</code>, in the same folder. If that name is taken, it suggests <code>report_merged (2).pdf</code>.</li><li><strong>Merge and save…</strong> stays greyed out while a page box has an error.</li><li><strong>Keep editing this file</strong> opens the merged PDF in Organize PDF.</li><li>A PDF that needs a password to open can&#39;t be added. Remove the password first with <a href="/tilepress/docs/security">Protect PDF</a>.</li></ul><h2 id="split-pdf" tabindex="-1">Split PDF <a class="header-anchor" href="#split-pdf" aria-label="Permalink to &quot;Split PDF&quot;">​</a></h2><p>Split PDF divides a PDF into separate files, or copies chosen pages into a new file.</p><h3 id="how-to-use-it-1" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-1" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Split PDF</strong> and open a PDF.</li><li>Pick a mode: <strong>By ranges</strong>, <strong>Every N pages</strong> or <strong>Extract pages</strong>.</li><li>Fill in the field for that mode (see below). The page grid shows the result: each page gets a coloured number badge for the file it goes into, and pages that aren&#39;t used are dimmed.</li><li>Check the line next to the button, for example &quot;Creates 3 files&quot;.</li><li>Click <strong>Split and save to folder…</strong> and choose a folder.</li></ol><h3 id="options-1" tabindex="-1">Options <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>What you enter</th><th>Result</th></tr></thead><tbody><tr><td><strong>By ranges</strong></td><td>Page ranges, for example <code>1-3, 4-8, 9-</code>.</td><td>One file per range. When you open a file, this is filled in with its first and second half.</td></tr><tr><td><strong>Every N pages</strong></td><td><strong>Pages per file</strong> (default 1).</td><td>The document cut into files of that many pages. The last file may be shorter.</td></tr><tr><td><strong>Extract pages</strong></td><td>The pages to copy. Click pages in the grid to add or remove them, or type them, for example <code>1-3, 7</code>.</td><td>One file with those pages. Tick <strong>One file per page</strong> to get a separate file for each page instead (off by default).</td></tr></tbody></table><h3 id="good-to-know-1" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-1" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The folder dialog starts in the PDF&#39;s own folder.</li><li>Files are named after the original with the pages they hold: <code>report_p3.pdf</code> for one page, <code>report_p1-4.pdf</code> for a run of pages, and <code>report_part2.pdf</code> (the file&#39;s number) for anything else. An existing file is never replaced: the new one gets <code> (2)</code>, <code> (3)</code> and so on.</li><li>In <strong>By ranges</strong>, ranges may overlap. A page that is in two ranges goes into both files.</li><li>In <strong>Extract pages</strong>, pages are written in page order, whatever order you type them in.</li><li>The <strong>Saved</strong> card lists up to 12 files and says how many more there are. <strong>Keep editing this file</strong> appears only when the split made a single file.</li></ul><h2 id="organize-pdf" tabindex="-1">Organize PDF <a class="header-anchor" href="#organize-pdf" aria-label="Permalink to &quot;Organize PDF&quot;">​</a></h2><p>Organize PDF lets you rearrange a document page by page: reorder, rotate, duplicate and delete pages, and insert blank pages or pages from another PDF.</p><p><img src="'+n+'" alt="Organize PDF showing the pages of a report as thumbnails"></p><h3 id="how-to-use-it-2" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-2" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Organize PDF</strong> and open a PDF. Every page appears as a thumbnail.</li><li>Click a page to select it. <kbd>Ctrl</kbd>-click adds or removes pages from the selection, and <kbd>Shift</kbd>-click selects a run of pages. Clicking an empty part of the grid clears the selection.</li><li>Change the pages: <ul><li>Drag a page to a new place. If it&#39;s part of the selection, all selected pages move together.</li><li>Use the toolbar buttons <strong>Left</strong>, <strong>Right</strong> (rotate by 90°), <strong>Duplicate</strong> and <strong>Delete</strong> on the selected pages.</li><li>Or hover over a page and use its own <strong>Rotate left</strong>, <strong>Rotate right</strong>, <strong>Duplicate</strong> and <strong>Delete</strong> buttons. These act on the whole selection if that page is selected, otherwise on that page alone.</li><li>Click <strong>Blank page</strong> to insert an empty page.</li><li>Click <strong>Insert PDF…</strong> to insert all pages of another PDF, or drag a PDF from the Explorer onto the grid where you want its pages.</li></ul></li><li>Use the undo and redo buttons if you change your mind, or <strong>Reset</strong> to go back to the original pages.</li><li>Click <strong>Save PDF…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><h3 id="options-2" tabindex="-1">Options <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Left</strong> / <strong>Right</strong></td><td>Rotate the selected pages 90° anticlockwise or clockwise.</td></tr><tr><td><strong>Duplicate</strong></td><td>Places a copy right after each selected page.</td></tr><tr><td><strong>Delete</strong></td><td>Removes the selected pages.</td></tr><tr><td><strong>Blank page</strong></td><td>Inserts an empty page after the last selected page, or at the end if nothing is selected. It has the same size as the page before it (A4 if there is none).</td></tr><tr><td><strong>Insert PDF…</strong></td><td>Inserts every page of another PDF after the last selected page, or at the end. The inserted pages are selected afterwards.</td></tr><tr><td>Undo / Redo</td><td>Steps back and forward through your changes (up to 100 steps).</td></tr><tr><td><strong>Reset</strong></td><td>Throws away all changes and shows the original pages again.</td></tr></tbody></table><p>Each thumbnail shows its new position and where it came from: <code>p. 3</code> for page 3 of the open file, the file name and page for an inserted PDF, or <code>Blank</code>.</p><h3 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h3><p>Click the page grid first so it has the keyboard focus.</p><table tabindex="0"><thead><tr><th>Keys</th><th>Action</th></tr></thead><tbody><tr><td><kbd>Delete</kbd> or <kbd>Backspace</kbd></td><td>Delete the selected pages</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>A</kbd></td><td>Select all pages</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Z</kbd></td><td>Undo</td></tr><tr><td><kbd>Ctrl</kbd>+<kbd>Y</kbd> or <kbd>Ctrl</kbd>+<kbd>Shift</kbd>+<kbd>Z</kbd></td><td>Redo</td></tr><tr><td><kbd>Esc</kbd></td><td>Clear the selection</td></tr></tbody></table><h3 id="good-to-know-2" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-2" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Save PDF…</strong> stays greyed out until you&#39;ve changed something.</li><li>The Save dialog suggests the original name with <code>_organized</code> added, for example <code>report_organized.pdf</code>.</li><li>Pages are copied as they are, not re-rendered, so text stays selectable and quality is unchanged. Rotation is added to any rotation the page already had.</li><li>If you delete every page, the grid says so; undo, insert pages, or drop a PDF onto it before you can save.</li></ul><h2 id="rotate-pdf" tabindex="-1">Rotate PDF <a class="header-anchor" href="#rotate-pdf" aria-label="Permalink to &quot;Rotate PDF&quot;">​</a></h2><p>Rotate PDF turns pages by 90°, 180° or 270°. You can rotate single pages, a selection, odd or even pages, or the whole document. The thumbnails show the result straight away.</p><h3 id="how-to-use-it-3" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-3" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Rotate PDF</strong> and open a PDF.</li><li>Choose which pages to turn: click pages to select them, or use <strong>All</strong>, <strong>Odd</strong> or <strong>Even</strong> next to <strong>Select</strong>. <strong>None</strong> clears the selection.</li><li>Click <strong>90° left</strong>, <strong>90° right</strong> or <strong>180°</strong>. With no pages selected, these turn every page. You can click them more than once.</li><li>To turn a single page, hover over it and use its <strong>Rotate left</strong> or <strong>Rotate right</strong> button.</li><li>Click <strong>Save rotated PDF…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><h3 id="options-3" tabindex="-1">Options <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>All</strong>, <strong>Odd</strong>, <strong>Even</strong>, <strong>None</strong></td><td>Select every page, pages 1, 3, 5…, pages 2, 4, 6…, or nothing.</td></tr><tr><td><strong>90° left</strong>, <strong>90° right</strong>, <strong>180°</strong></td><td>Rotate the selected pages, or all pages if none are selected. The text in brackets says which.</td></tr><tr><td><strong>Reset</strong></td><td>Removes all the rotations you&#39;ve added.</td></tr></tbody></table><p>Each rotated page shows how far it has been turned, for example <code>+90°</code>.</p><h3 id="good-to-know-3" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-3" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><strong>Save rotated PDF…</strong> stays greyed out until at least one page is rotated. The bar shows how many pages are rotated.</li><li>The Save dialog suggests the original name with <code>_rotated</code> added.</li><li>Rotation only changes how the page is displayed. Nothing is re-rendered, so there is no loss of quality.</li></ul><h2 id="crop-pdf" tabindex="-1">Crop PDF <a class="header-anchor" href="#crop-pdf" aria-label="Permalink to &quot;Crop PDF&quot;">​</a></h2><p>Crop PDF trims the margins of pages. On screen the tool is called <strong>Crop</strong>. You can drag a box on the page, type the margins in millimetres, or let the tool find the content for you.</p><h3 id="how-to-use-it-4" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-4" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Crop</strong> and open a PDF. The current page is shown with the crop box on top. Use the arrows or the page number under it to move between pages.</li><li>Set the box in any of these ways: <ul><li>Drag the box to move it, or drag its corners and edges to resize it.</li><li>Press outside the box and drag to draw a new one.</li><li>Type the margins under <strong>Margins (mm)</strong>: <strong>Top</strong>, <strong>Right</strong>, <strong>Bottom</strong> and <strong>Left</strong>.</li><li>Click <strong>Auto-detect content</strong> to fit the box around what&#39;s printed on the current page.</li></ul></li><li>Check the line under the margins, for example &quot;Page 1 becomes 180 × 250 mm&quot;.</li><li>Under <strong>Apply to</strong>, choose <strong>All pages</strong>, <strong>Only page</strong> <em>N</em> (the page on screen), or <strong>Pages</strong> and type a list such as <code>2-5, 8</code>.</li><li>Click <strong>Save cropped PDF…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><h3 id="options-4" tabindex="-1">Options <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Top</strong>, <strong>Right</strong>, <strong>Bottom</strong>, <strong>Left</strong></td><td>How much to trim from each side, in millimetres (steps of 0.5 mm).</td><td>0</td></tr><tr><td><strong>Auto-detect content</strong></td><td>Looks at the current page for anything that isn&#39;t white and sets the margins to just outside it, leaving about 2 mm.</td><td></td></tr><tr><td><strong>Reset</strong></td><td>Sets all margins back to 0.</td><td></td></tr><tr><td><strong>Apply to</strong></td><td><strong>All pages</strong>, <strong>Only page</strong> <em>N</em>, or <strong>Pages</strong> with a list.</td><td>All pages</td></tr></tbody></table><h3 id="good-to-know-4" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-4" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li>The same margins are trimmed from every chosen page, measured from each page&#39;s own edges. Auto-detect uses the page on screen only, so check other pages if their layout differs.</li><li>Margins are measured on the page as you see it, so rotated pages are cropped correctly.</li><li>What&#39;s left must be at least 18 points (about 6.4 mm) wide and high. If the margins leave less, the size line turns red and saving fails with &quot;The margins leave nothing of page <em>N</em>&quot;.</li><li>The Save dialog suggests the original name with <code>_cropped</code> added.</li></ul><div class="warning custom-block"><p class="custom-block-title">Cropping hides, it doesn&#39;t delete</p><p>Content outside the box is hidden, not removed. It&#39;s still in the file and can come back if someone changes the page box. To really remove something, use <strong>Redact</strong> in <a href="/tilepress/docs/edit">Edit PDF</a>.</p></div><h2 id="page-numbers" tabindex="-1">Page numbers <a class="header-anchor" href="#page-numbers" aria-label="Permalink to &quot;Page numbers&quot;">​</a></h2><p>Page numbers stamps a number on each page. You choose the position, the format, which pages are numbered and the number to start from. The preview shows the number on the page as you change the settings.</p><h3 id="how-to-use-it-5" tabindex="-1">How to use it <a class="header-anchor" href="#how-to-use-it-5" aria-label="Permalink to &quot;How to use it&quot;">​</a></h3><ol><li>Open <strong>Page numbers</strong> and open a PDF.</li><li>Under <strong>Position</strong>, click one of the six spots: top or bottom, left, centre or right.</li><li>Under <strong>Format</strong>, pick a format, or <strong>Custom…</strong> and type your own.</li><li>Under <strong>Pages</strong>, set <strong>Number pages</strong> from and to, and the <strong>First number</strong>.</li><li>Under <strong>Style</strong>, set the <strong>Size (pt)</strong>, <strong>Margin (mm)</strong> and <strong>Colour</strong>.</li><li>Use the arrows under the preview to check other pages. Pages that won&#39;t get a number say &quot;Not numbered&quot;.</li><li>Click <strong>Add numbers and save…</strong>, choose a name and folder, and click <strong>Save</strong>.</li></ol><h3 id="options-5" tabindex="-1">Options <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>What it does</th><th>Default</th></tr></thead><tbody><tr><td><strong>Position</strong></td><td>Where the number goes: top or bottom, and left, centre or right.</td><td>Bottom centre</td></tr><tr><td><strong>Mirror on even pages (double-sided)</strong></td><td>On even pages, left and right swap, so numbers sit on the outer edge when printed on both sides. Has no effect on centred numbers.</td><td>Off</td></tr><tr><td><strong>Format</strong></td><td><code>1</code>, <code>Page 1</code>, <code>Page 1 of 9</code>, <code>1 / 9</code>, <code>- 1 -</code>, or <strong>Custom…</strong>.</td><td><code>1</code></td></tr><tr><td>Custom format</td><td>Your own text. <code>{n}</code> is the number and <code>{total}</code> is the last number used, for example <code>Report – {n}/{total}</code>. It must contain <code>{n}</code>.</td><td><code>Page {n}</code></td></tr><tr><td><strong>Number pages</strong> … <strong>to</strong> …</td><td>The first and last page to number. Pages outside this range are left alone.</td><td>The whole document</td></tr><tr><td><strong>First number</strong></td><td>The number printed on the first numbered page.</td><td>1</td></tr><tr><td><strong>Size (pt)</strong></td><td>Text size, from 4 to 96 points.</td><td>11</td></tr><tr><td><strong>Margin (mm)</strong></td><td>Distance from the edges of the page.</td><td>12</td></tr><tr><td><strong>Colour</strong></td><td><strong>Black</strong>, <strong>Dark grey</strong>, <strong>Grey</strong>, <strong>White</strong>, or <strong>Custom</strong> with a colour picker.</td><td>Black</td></tr></tbody></table><h3 id="good-to-know-5" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know-5" aria-label="Permalink to &quot;Good to know&quot;">​</a></h3><ul><li><code>{total}</code> is the last number printed, not the page count. If you number pages 3 to 10 starting at 1, <code>{total}</code> is 8.</li><li><strong>Mirror on even pages</strong> goes by the page&#39;s position in the file, not by the number printed on it.</li><li>Numbers are written in the standard Helvetica font, so use Latin characters. Characters that font can&#39;t show are printed as <code>?</code>.</li><li>On pages that are rotated, the number goes at the top or bottom as you see the page.</li><li><strong>Add numbers and save…</strong> stays greyed out while the format has no <code>{n}</code>, the page range is wrong, or the size is outside 4–96 pt. The reason is shown in red above the button.</li><li>The Save dialog suggests the original name with <code>_numbered</code> added.</li></ul>',62)])])}const b=o(i,[["render",d]]);export{f as __pageData,b as default};
